    alertLevel: 'high',
    sources: ['Azerbaijan State Social Protection Fund (SSPF)', 'Operative Information Center'],
    sourceUrl: 'https://operativmm.az/en/post/sspf-warns-of-1000-azn-payment-scam-in-azerbaijan/67900',
    country: 'AZ',
